mapper.select:
SELECT /* LGVPAYP0021.retrievePayrollRunEmpList */ pcee.employee_no AS employee_no , em.full_name_local AS employee_name , em.org_name_local AS organization_name , TO_CHAR(em.date_hire_subsidiary,'dd/mm/yyyy') AS hire_date , TO_CHAR(em.date_retire,'dd/mm/yyyy') AS resignation_date
FROM tb_pay_calc_emp_exec_n pcee , emp_master em
WHERE pcee.payroll_calculation_exec_id IN
#{payrollCalculationExecIdList[${idx}], jdbcType=NUMERIC}
WHERE 1=2
AND pcee.employee_no = #{employeeNo}
AND NVL(pcee.error_flag, 'N') = 'N' /* 정상건만 조회 */ AND em.employee_number = pcee.employee_no
AND em.organization_id = #{organizationId, jdbcType=NUMERIC}
GROUP BY pcee.employee_no , em.full_name_local , em.org_name_local , TO_CHAR(em.date_hire_subsidiary,'dd/mm/yyyy') , TO_CHAR(em.date_retire,'dd/mm/yyyy')
ORDER BY pcee.employee_no
